-- Verified Tobacco Road and Pinehurst course catalog.
-- Apply after 003_2027_planning.sql. Source conflicts are preserved as notes; ratings are never inferred.

alter table public.courses add column if not exists source_url text;
alter table public.courses add column if not exists source_notes text;
alter table public.courses add column if not exists available_from date;
alter table public.courses add column if not exists unavailable_until date;

alter table public.tees drop constraint if exists tees_course_id_name_key;
alter table public.tees drop constraint if exists tees_slope_check;
alter table public.tees drop constraint if exists tees_par_check;
alter table public.tees drop constraint if exists tees_yardage_check;
alter table public.tees alter column rating drop not null;
alter table public.tees alter column slope drop not null;
alter table public.tees add column if not exists rating_category text not null default 'U';
alter table public.tees add column if not exists rating_par integer;
alter table public.tees add column if not exists source_url text;
alter table public.tees add column if not exists source_notes text;
alter table public.tees add constraint tees_rating_check check (rating is null or rating between 20 and 90);
alter table public.tees add constraint tees_slope_check check (slope is null or slope between 55 and 155);
alter table public.tees add constraint tees_par_check check (par between 27 and 90);
alter table public.tees add constraint tees_rating_par_check check (rating_par is null or rating_par between 27 and 90);
alter table public.tees add constraint tees_yardage_check check (yardage between 500 and 9000);
create unique index if not exists tees_course_name_category_idx
  on public.tees(course_id, lower(name), rating_category);

alter table public.holes drop constraint if exists holes_tee_id_stroke_index_key;
alter table public.holes drop constraint if exists holes_yardage_check;
alter table public.holes alter column stroke_index drop not null;
alter table public.holes add constraint holes_yardage_check check (yardage between 25 and 750);
create unique index if not exists holes_tee_stroke_index_idx
  on public.holes(tee_id, stroke_index) where stroke_index is not null;

create or replace function public.seed_verified_course_catalog(payload jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  course_id_value uuid;
  tee_id_value uuid;
  tee_record jsonb;
  rating_record jsonb;
  hole_record record;
  category_value text;
  stroke_values jsonb;
begin
  select id into course_id_value from public.courses where lower(name) = lower(payload ->> 'name') order by created_at limit 1;
  if course_id_value is null then
    insert into public.courses(name, location, active, source_url, source_notes, available_from, unavailable_until)
    values (payload ->> 'name', payload ->> 'location', (payload ->> 'active')::boolean, payload ->> 'source_url', payload ->> 'source_notes', nullif(payload ->> 'available_from', '')::date, nullif(payload ->> 'unavailable_until', '')::date)
    returning id into course_id_value;
  else
    update public.courses set
      location = payload ->> 'location', active = (payload ->> 'active')::boolean,
      source_url = payload ->> 'source_url', source_notes = payload ->> 'source_notes',
      available_from = nullif(payload ->> 'available_from', '')::date,
      unavailable_until = nullif(payload ->> 'unavailable_until', '')::date
    where id = course_id_value;
  end if;

  for tee_record in select value from jsonb_array_elements(coalesce(payload -> 'tees', '[]'::jsonb)) loop
    for rating_record in select value from jsonb_array_elements(tee_record -> 'ratings') loop
      category_value := rating_record ->> 'category';
      select id into tee_id_value from public.tees
      where course_id = course_id_value and lower(name) = lower(tee_record ->> 'name') and rating_category = category_value
      limit 1;
      if tee_id_value is null then
        insert into public.tees(course_id, name, rating_category, rating, slope, par, rating_par, yardage, source_url, source_notes)
        values (course_id_value, tee_record ->> 'name', category_value,
          nullif(rating_record ->> 'rating', '')::numeric, nullif(rating_record ->> 'slope', '')::integer,
          (select sum(value::integer) from jsonb_array_elements_text(tee_record -> 'pars')),
          nullif(rating_record ->> 'rating_par', '')::integer,
          (select sum(value::integer) from jsonb_array_elements_text(tee_record -> 'yardages')),
          payload ->> 'source_url', tee_record ->> 'source_notes')
        returning id into tee_id_value;
      else
        update public.tees set
          rating = nullif(rating_record ->> 'rating', '')::numeric,
          slope = nullif(rating_record ->> 'slope', '')::integer,
          par = (select sum(value::integer) from jsonb_array_elements_text(tee_record -> 'pars')),
          rating_par = nullif(rating_record ->> 'rating_par', '')::integer,
          yardage = (select sum(value::integer) from jsonb_array_elements_text(tee_record -> 'yardages')),
          source_url = payload ->> 'source_url', source_notes = tee_record ->> 'source_notes'
        where id = tee_id_value;
      end if;

      delete from public.holes where tee_id = tee_id_value;
      stroke_values := case when category_value = 'F' and tee_record ? 'female_stroke_indexes'
        then tee_record -> 'female_stroke_indexes' else tee_record -> 'stroke_indexes' end;
      for hole_record in
        select ordinality::integer as hole_number, yardage::integer, par_value::integer,
          case when stroke_value = 'null' then null else stroke_value::integer end as stroke_index
        from jsonb_array_elements_text(tee_record -> 'yardages') with ordinality yards(yardage, ordinality)
        join jsonb_array_elements_text(tee_record -> 'pars') with ordinality pars(par_value, par_position) on par_position = ordinality
        join jsonb_array_elements_text(stroke_values) with ordinality strokes(stroke_value, stroke_position) on stroke_position = ordinality
      loop
        insert into public.holes(tee_id, hole_number, par, stroke_index, yardage)
        values (tee_id_value, hole_record.hole_number, hole_record.par_value, hole_record.stroke_index, hole_record.yardage);
      end loop;
    end loop;
  end loop;
end;
$$;

select public.seed_verified_course_catalog($catalog$
